DOCUMENT();

loadMacros(
  "PGstandard.pl",
  "MathObjects.pl",
  "contextFraction.pl",
  "PGgraphmacros.pl",
  "unionTables.pl",
  "VectorField2D.pl",
  "PGcourse.pl"
);

TEXT(beginproblem());

$refreshCachedImages=1;

#####################################
#  Setup

Context("Numeric")->variables->are(x=>"Real",y=>"Real");

$a = random(2,4,1);
$b = random(2,4,1);
$c = random(2,5,1);
while ($c==$b) { $b = random(2,4,1); }

$F = "($a x - $b y) \vec{i} + $c x \vec{j}";

$r = random(2,4,1);
$rr = $r * $r;

$d = list_random(6,4,3);

if ($d == 6) {

  $answer = Compute("($b + $c) pi $rr / 12"); 
  $x = $r * sqrt(3)/2;
  $y = $r/2;

} elsif ($d == 4) {

  $answer = Compute("($b + $c) pi $rr / 8");
  $x = $r / sqrt(2);
  $y = $r / sqrt(2);

} else {

  $answer = Compute("($b + $c) pi $rr / 6");
  $x = $r/2;
  $y = $r * sqrt(3)/2;

}


#######################
#  create graphs


foreach my $i (0) {
  $gr[$i] = init_graph(-1,-1,5,5,grid=>[6,6],axes=>[0,0],pixels=>[400,400]);
  $gr[$i]->lb('reset');
  foreach my $j (1..4) {
    $gr[$i]->lb( new Label(-0.7,  $j, $j,'black','center','middle'));
#    $gr[$i]->lb( new Label(-0.7, -$j,-$j,'black','center','middle'));
    $gr[$i]->lb( new Label(  $j,-0.7, $j,'black','center','middle'));
#    $gr[$i]->lb( new Label( -$j,-0.7,-$j,'black','center','middle'));
  }
  $gr[$i]->lb( new Label(4.7,0.2,'x','black','center','middle'));
  $gr[$i]->lb( new Label(0.2,4.7,'y','black','center','middle'));

  VectorField2D(
  graphobject => $gr[$i],
  Fx => Formula("$a x - $b y"),
  Fy => Formula("$c x"),
  xvar => "x",
  yvar => "y",
  xmin => -1,
  xmax =>  5,
  ymin => -1,
  ymax =>  5,
  xsamples => 12,
  ysamples => 12,
  vectorcolor => "blue",
  vectorscale => 0.03,
  vectorthickness => 2,
  );

}


